begin;
-- A temporary role transition verifies that legacy programme grants do not bypass CMS assignments.
update public.admin_profiles set role='content_manager' where id='7d8d6958-08a1-4eba-8d1a-26d710e41c9f';
select set_config('request.jwt.claim.sub','bc08518d-8006-4424-933f-1fd591451f64',true);
set local role authenticated;
do $$
declare p1 uuid;p2 uuid;e1 uuid;e2 uuid;b1 jsonb;b2 jsonb;v public.cms_entries%rowtype;old_live uuid;
begin
 select r.body into b1 from public.cms_entries e join public.cms_entry_revisions r on r.id=e.published_revision_id where e.kind='project' limit 1;
 select r.body into b2 from public.cms_entries e join public.cms_entry_revisions r on r.id=e.published_revision_id where e.kind='event' limit 1;
 p1:=public.cms_write_entry('project','qa-cms-project-one',b1,null,null,null,'save');
 select * into v from public.cms_entries where id=p1;
 perform public.cms_write_entry('project',v.slug,b1,null,v.draft_revision_id,v.published_revision_id,'publish');
 p2:=public.cms_write_entry('project','qa-cms-project-two',b1,null,null,null,'save');
 select * into v from public.cms_entries where id=p2;
 perform public.cms_write_entry('project',v.slug,b1,null,v.draft_revision_id,v.published_revision_id,'publish');
 e1:=public.cms_write_entry('event','qa-cms-event-one',b2,p1,null,null,'save');
 select * into v from public.cms_entries where id=e1;
 perform public.cms_write_entry('event',v.slug,b2,p1,v.draft_revision_id,v.published_revision_id,'publish');
 select * into v from public.cms_entries where id=e1;old_live:=v.published_revision_id;
 perform public.cms_write_entry('event',v.slug,jsonb_set(b2,'{title}','"Private draft title"'),p2,v.draft_revision_id,v.published_revision_id,'save');
 if not exists(select 1 from public.cms_entries where id=e1 and published_revision_id=old_live and published_project_id=p1 and project_id=p2)then raise exception 'Draft changed live content or relationship';end if;
 begin perform public.cms_write_entry('event',v.slug,b2,p1,v.draft_revision_id,v.published_revision_id,'save');raise exception 'Stale save was allowed';exception when serialization_failure then null;end;
 select * into v from public.cms_entries where id=e1;
 perform public.cms_write_entry('event',v.slug,'{}',p2,v.draft_revision_id,v.published_revision_id,'discard');
 if not exists(select 1 from public.cms_entries where id=e1 and project_id=p1 and draft_revision_id is null and published_revision_id=old_live)then raise exception 'Discard did not preserve the live version';end if;
 perform public.cms_assign_entry(p1,'7d8d6958-08a1-4eba-8d1a-26d710e41c9f',true,true,true,false);
 perform set_config('request.jwt.claim.sub','7d8d6958-08a1-4eba-8d1a-26d710e41c9f',true);
 if exists(select 1 from public.cms_entries where id=p2)then raise exception 'Unassigned project leaked through RLS';end if;
 if not exists(select 1 from public.cms_entries where id=p1)then raise exception 'Assigned project not visible';end if;
 e2:=public.cms_write_entry('event','qa-cms-delegated-event',b2,p1,null,null,'save');
 select * into v from public.cms_entries where id=e2;
 begin perform public.cms_write_entry('event',v.slug,b2,p1,v.draft_revision_id,v.published_revision_id,'publish');raise exception 'Editor published without permission';exception when insufficient_privilege then null;end;
 begin perform public.cms_write_entry('event','qa-cms-unauthorised',b2,p2,null,null,'save');raise exception 'Created content in an unassigned project';exception when insufficient_privilege then null;end;
 begin perform public.cms_write_entry('event',v.slug,b2,p2,v.draft_revision_id,v.published_revision_id,'save');raise exception 'Moved content across project boundaries';exception when insufficient_privilege then null;end;
 begin perform public.cms_assign_entry(p2,'7d8d6958-08a1-4eba-8d1a-26d710e41c9f',true,true,true,true);raise exception 'Content Manager changed permissions';exception when insufficient_privilege then null;end;
 perform set_config('request.jwt.claim.sub','bc08518d-8006-4424-933f-1fd591451f64',true);
 perform public.cms_assign_entry(p1,'7d8d6958-08a1-4eba-8d1a-26d710e41c9f',true,true,true,true);
 perform set_config('request.jwt.claim.sub','7d8d6958-08a1-4eba-8d1a-26d710e41c9f',true);
 select * into v from public.cms_entries where id=e2;
 perform public.cms_write_entry('event',v.slug,b2,p1,v.draft_revision_id,v.published_revision_id,'publish');
 if not exists(select 1 from public.cms_entries where id=e2 and published_revision_id is not null and draft_revision_id is null)then raise exception 'Delegated publishing failed';end if;
 perform set_config('request.jwt.claim.sub','bc08518d-8006-4424-933f-1fd591451f64',true);
 select * into v from public.cms_entries where id=e2;
 perform public.cms_write_entry('event',v.slug,'{}',p1,v.draft_revision_id,v.published_revision_id,'archive');
 select * into v from public.cms_entries where id=e2;
 if not v.archived or v.published_revision_id is not null or v.draft_revision_id is null then raise exception 'Archive lost the content';end if;
 perform public.cms_write_entry('event',v.slug,'{}',p1,v.draft_revision_id,v.published_revision_id,'recover');
 if not exists(select 1 from public.cms_entries where id=e2 and not archived and published_revision_id is null and draft_revision_id is not null)then raise exception 'Recovery should leave a private draft';end if;
end $$;
rollback;
select jsonb_build_object('retained_test_entries',(select count(*) from public.cms_entries where slug like 'qa-cms-%'),'anon_reads',has_table_privilege('anon','public.cms_entry_revisions','select'),'browser_writes',has_table_privilege('authenticated','public.cms_entries','update'),'projects',(select count(*) from public.cms_entries where kind='project'),'events',(select count(*) from public.cms_entries where kind='event')) as result;
